            if defn.constraint_class == "HARD" and defn.type == "string"
        }
        registry_hard_strings = set(HARD_STRINGS.keys())
        missing_str = registry_hard_strings - schema_hard_strings
        if missing_str:
            results["schema_coverage/hard_strings"] = (
                f"Schema missing HARD string constraints: {sorted(missing_str)}"
            )

        # New: validate every config file’s values against schema
        layer_order = {"universal": 0, "domain": 1, "task": 2, "model": 3}
        configs_to_check = [
            ("universal", REGISTRY_DIR / "universal.toml"),
        ]
        domains_dir = REGISTRY_DIR / "domains"
        if domains_dir.exists():
            for p in domains_dir.glob("*.toml"):
                configs_to_check.append((f"domain/{p.stem}", p))
        tasks_dir = REGISTRY_DIR / "tasks"
        if tasks_dir.exists():
            for p in tasks_dir.glob("*.toml"):
                configs_to_check.append((f"task/{p.stem}", p))
        models_dir = REGISTRY_DIR / "models"
        if models_dir.exists():
            for p in models_dir.glob("*.toml"):
                configs_to_check.append((f"model/{p.stem}", p))

        for layer_name, path in configs_to_check:
            if not path.exists():
                continue
            try:
                config = _load_toml(path)
                flat = _flatten_dict(config)
                for dotpath, value in flat.items():
                    if dotpath not in self._schema:
                        results[f"{layer_name}/unknown_param"] = (
                            f"Parameter '{dotpath}' not defined in schema"
                        )
                        continue
                    defn = self._schema[dotpath]
                    # Type checking
                    if defn.type == "bool" and not isinstance(value, bool):
                        results[f"{layer_name}/type_mismatch"] = (
                            f"'{dotpath}': expected bool, got {type(value).__name__}"
                        )
                    elif defn.type == "int" and not isinstance(value, int):
                        results[f"{layer_name}/type_mismatch"] = (
                            f"'{dotpath}': expected int, got {type(value).__name__}"
                        )
                    elif defn.type == "float" and not isinstance(value, (int, float)):
                        results[f"{layer_name}/type_mismatch"] = (
                            f"'{dotpath}': expected float, got {type(value).__name__}"
                        )
                    elif defn.type == "string" and not isinstance(value, str):
                        results[f"{layer_name}/type_mismatch"] = (
                            f"'{dotpath}': expected string, got {type(value).__name__}"
                        )
                    # Enum/allowed_values validation
                    if defn.allowed_values is not None and value not in defn.allowed_values:
                        results[f"{layer_name}/enum_violation"] = (
                            f"'{dotpath}': value {value!r} not in {defn.allowed_values}"
                        )
                    # min_layer validation
                    layer_level = layer_order.get(layer_name.split('/')[0], 4)
                    min_level = layer_order.get(defn.min_layer, 4)
                    if layer_level < min_level:
                        results[f"{layer_name}/min_layer"] = (
                            f"'{dotpath}' defined in {layer_name} "
                            f"but min_layer is {defn.min_layer}"
                        )
            except Exception as e:
                results[f"{layer_name}/load_error"] = str(e)

        return results  
